// The ZKTeco / eSSL "4370" protocol, read side only (docs/plans/PHASE_2.md
// "P2-F build design", D-F1). Pure functions: framing, checksum, the comm-key
// handshake, time and record decoding. Ported from pyzk 0.9 (the widely used
// reference implementation) and pinned by vectors generated by running pyzk
// itself (__tests__/fixtures/pyzk-vectors.json).

export const USHRT_MAX = 65535;

/** Command and reply codes (pyzk zk/const.py). Only what this agent uses, plus the write commands it must never send (named so the allowlist test can prove it). */
export const CMD = {
  CONNECT: 1000,
  EXIT: 1001,
  AUTH: 1102,
  OPTIONS_RRQ: 11,
  ATTLOG_RRQ: 13,
  GET_FREE_SIZES: 50,
  GET_TIME: 201,
  GET_VERSION: 1100,
  PREPARE_DATA: 1500,
  DATA: 1501,
  FREE_DATA: 1502,
  PREPARE_BUFFER: 1503,
  READ_BUFFER: 1504,
  // Replies.
  ACK_OK: 2000,
  ACK_ERROR: 2001,
  ACK_DATA: 2002,
  ACK_UNAUTH: 2005,
} as const;

/** Commands that change a device. The driver can't send any of them (see READ_ONLY_COMMANDS); listed for the tests. */
export const WRITE_COMMANDS = {
  USER_WRQ: 8,
  USERTEMP_WRQ: 10,
  OPTIONS_WRQ: 12,
  CLEAR_DATA: 14,
  CLEAR_ATTLOG: 15,
  DELETE_USER: 18,
  DELETE_USERTEMP: 19,
  CLEAR_ADMIN: 20,
  UNLOCK: 31,
  CLEAR_ACC: 32,
  CLEAR_OPLOG: 33,
  SET_TIME: 202,
  ENABLEDEVICE: 1002,
  DISABLEDEVICE: 1003,
  RESTART: 1004,
  POWEROFF: 1005,
  SLEEP: 1006,
  REFRESHDATA: 1013,
  TESTVOICE: 1017,
  REG_EVENT: 500,
} as const;

/**
 * Rule 1 of P2-F, structurally: the ONLY commands this agent can send. Each
 * reads, or opens/closes a session, or frees the device's own transfer
 * buffer after a read. Nothing that writes, clears, sets the clock, pauses
 * the device or touches users. `send` refuses anything else.
 */
export const READ_ONLY_COMMANDS: ReadonlySet<number> = new Set([
  CMD.CONNECT,
  CMD.AUTH,
  CMD.EXIT,
  CMD.OPTIONS_RRQ,
  CMD.GET_VERSION,
  CMD.GET_FREE_SIZES,
  CMD.GET_TIME,
  CMD.PREPARE_BUFFER,
  CMD.READ_BUFFER,
  CMD.FREE_DATA,
]);
/** The buffered read (PREPARE_BUFFER) may only ever fetch the attendance log. */
export const READ_ONLY_BUFFERED: ReadonlySet<number> = new Set([CMD.ATTLOG_RRQ]);

export const TCP_MAGIC_1 = 0x5050;
export const TCP_MAGIC_2 = 0x7d82;
/** Largest chunk per buffered read, as pyzk: TCP 0xFFC0, UDP 16 KiB. */
export const MAX_CHUNK_TCP = 0xffc0;
export const MAX_CHUNK_UDP = 16 * 1024;

// ── Packets ──────────────────────────────────────────────────────────────

/** pyzk __create_checksum (from zkemsdk.c): one's-complement-style 16-bit sum. */
export function checksum(bytes: Uint8Array): number {
  let sum = 0;
  let i = 0;
  let left = bytes.length;
  while (left > 1) {
    sum += bytes[i]! | (bytes[i + 1]! << 8);
    i += 2;
    if (sum > USHRT_MAX) sum -= USHRT_MAX;
    left -= 2;
  }
  if (left) sum += bytes[bytes.length - 1]!;
  while (sum > USHRT_MAX) sum -= USHRT_MAX;
  sum = -sum - 1; // Python's ~ on an int
  while (sum < 0) sum += USHRT_MAX;
  return sum;
}

/**
 * One request packet (pyzk __create_header): an 8-byte header — command,
 * checksum, session, reply id — then the data. As pyzk does, the checksum is
 * computed with the *current* reply id, and the packet carries the next one.
 */
export function buildPacket(command: number, data: Uint8Array, session: number, replyId: number): Buffer {
  const head = Buffer.alloc(8);
  head.writeUInt16LE(command, 0);
  head.writeUInt16LE(0, 2);
  head.writeUInt16LE(session, 4);
  head.writeUInt16LE(replyId, 6);
  const sum = checksum(Buffer.concat([head, data]));
  let next = replyId + 1;
  if (next >= USHRT_MAX) next -= USHRT_MAX;
  head.writeUInt16LE(sum, 2);
  head.writeUInt16LE(next, 6);
  return Buffer.concat([head, data]);
}

export interface Packet {
  command: number;
  checksum: number;
  session: number;
  replyId: number;
  data: Buffer;
}

export function parsePacket(buf: Buffer): Packet {
  if (buf.length < 8) throw new ProtocolError(`Packet too short (${buf.length} bytes).`);
  return { command: buf.readUInt16LE(0), checksum: buf.readUInt16LE(2), session: buf.readUInt16LE(4), replyId: buf.readUInt16LE(6), data: buf.subarray(8) };
}

/** A reply packet as a device sends it (the fake device uses this). */
export function buildReply(code: number, data: Uint8Array, session: number, replyId: number): Buffer {
  const head = Buffer.alloc(8);
  head.writeUInt16LE(code, 0);
  head.writeUInt16LE(0, 2);
  head.writeUInt16LE(session, 4);
  head.writeUInt16LE(replyId, 6);
  head.writeUInt16LE(checksum(Buffer.concat([head, data])), 2);
  return Buffer.concat([head, data]);
}

/** TCP wraps every packet in an 8-byte top: two magic words, then the packet's length. */
export function tcpFrame(packet: Buffer): Buffer {
  const top = Buffer.alloc(8);
  top.writeUInt16LE(TCP_MAGIC_1, 0);
  top.writeUInt16LE(TCP_MAGIC_2, 2);
  top.writeUInt32LE(packet.length, 4);
  return Buffer.concat([top, packet]);
}

/** Splits a TCP byte stream into packets, however the network fragments or joins them. */
export class TcpDeframer {
  private buf: Buffer = Buffer.alloc(0);

  push(chunk: Buffer): Buffer[] {
    this.buf = this.buf.length ? Buffer.concat([this.buf, chunk]) : chunk;
    const out: Buffer[] = [];
    while (this.buf.length >= 8) {
      if (this.buf.readUInt16LE(0) !== TCP_MAGIC_1 || this.buf.readUInt16LE(2) !== TCP_MAGIC_2) {
        throw new ProtocolError("The device sent bytes that aren't a protocol packet (lost framing).");
      }
      const len = this.buf.readUInt32LE(4);
      if (len < 8 || len > 16 * 1024 * 1024) throw new ProtocolError(`Implausible packet length ${len}.`);
      if (this.buf.length < 8 + len) break;
      out.push(this.buf.subarray(8, 8 + len));
      this.buf = this.buf.subarray(8 + len);
    }
    return out;
  }
}

// ── The comm key ─────────────────────────────────────────────────────────

/**
 * pyzk make_commkey (from the vendor's commpro.c, MakeKey): the device's
 * connection password scrambled with the session id. pyzk raises if the
 * intermediate exceeds 32 bits; the C original wraps, as here.
 */
export function makeCommKey(key: number, session: number, ticks = 50): Buffer {
  let k = 0;
  for (let i = 0; i < 32; i++) {
    const bit = Math.floor(key / 2 ** i) % 2;
    k = k * 2 + bit;
  }
  k = (k + session) % 2 ** 32;
  const b = Buffer.alloc(4);
  b.writeUInt32LE(k, 0);
  const x = [b[0]! ^ 0x5a, b[1]! ^ 0x4b, b[2]! ^ 0x53, b[3]! ^ 0x4f]; // "ZKSO"
  const y = [x[2]!, x[3]!, x[0]!, x[1]!]; // the two 16-bit halves swapped
  const t = ticks & 0xff;
  return Buffer.from([y[0]! ^ t, y[1]! ^ t, t, y[3]! ^ t]);
}

// ── Time ─────────────────────────────────────────────────────────────────

const pad = (n: number, w = 2) => String(n).padStart(w, "0");

/**
 * Device time is wall-clock time with no zone, packed into seconds since
 * 2000-01-01 on a 31-day-month calendar (pyzk __encode_time). Decoded straight
 * to "YYYY-MM-DD HH:MM:SS" — never through a JavaScript Date — so the PC's
 * own timezone can't touch a punch time (the zkteco-js finding, D-F1).
 */
export function decodeTime(t: number): string {
  let v = t;
  const second = v % 60;
  v = Math.floor(v / 60);
  const minute = v % 60;
  v = Math.floor(v / 60);
  const hour = v % 24;
  v = Math.floor(v / 24);
  const day = (v % 31) + 1;
  v = Math.floor(v / 31);
  const month = (v % 12) + 1;
  v = Math.floor(v / 12);
  const year = v + 2000;
  return `${year}-${pad(month)}-${pad(day)} ${pad(hour)}:${pad(minute)}:${pad(second)}`;
}

export function encodeTime(local: string): number {
  const m = /^(\d{4})-(\d{2})-(\d{2}) (\d{2}):(\d{2}):(\d{2})$/.exec(local);
  if (!m) throw new Error(`Not a local timestamp: ${local}`);
  const [y, mo, d, h, mi, s] = m.slice(1).map(Number) as [number, number, number, number, number, number];
  return ((y % 100) * 12 * 31 + (mo - 1) * 31 + d - 1) * 86400 + (h * 60 + mi) * 60 + s;
}

// ── Records ──────────────────────────────────────────────────────────────

/** One attendance record exactly as the device stores it, before it becomes an ATTLOG line. */
export interface AttRecord {
  deviceUserId: string;
  /** Device-local "YYYY-MM-DD HH:MM:SS". */
  localTime: string;
  /** The punch state byte (ATTLOG's status column). Our device always records 1-style "no direction"; never relied on. */
  status: string;
  /** The verify type byte (fingerprint, face, finger-vein…). Stored, never relied on. */
  verifyMode: string;
  workcode: string;
}

export type RecordFormat = 40 | 16;

/**
 * The attendance buffer: 4 bytes of total size, then fixed-size records
 * (pyzk get_attendance). The record size is total ÷ the device's record count;
 * a punch arriving between the count and the read can upset that, so an exact
 * multiple of 40 (then 16) is accepted too. 8-byte records (very old firmware,
 * user ids only through the user table) aren't read: UNSUPPORTED_FORMAT.
 */
export function decodeAttendance(buffer: Buffer, recordCountHint: number | null): { format: RecordFormat; records: AttRecord[] } {
  if (buffer.length < 4) return { format: 40, records: [] };
  const total = buffer.readUInt32LE(0);
  const body = buffer.subarray(4, 4 + total);
  if (total === 0) return { format: 40, records: [] };
  if (body.length < total) throw new ProtocolError(`Attendance data cut short: ${body.length} of ${total} bytes.`);
  const ratio = recordCountHint ? total / recordCountHint : NaN;
  const format: RecordFormat | null = ratio === 40 ? 40 : ratio === 16 ? 16 : total % 40 === 0 ? 40 : total % 16 === 0 ? 16 : null;
  if (!format) throw new UnsupportedFormatError(`Attendance records of ${recordCountHint ? `${ratio} bytes` : "unknown size"} (${total} bytes in all) aren't a layout this driver reads.`);
  const records: AttRecord[] = [];
  for (let off = 0; off + format <= body.length; off += format) {
    const r = body.subarray(off, off + format);
    records.push(format === 40 ? decodeRecord40(r) : decodeRecord16(r));
  }
  return { format, records };
}

/** '<H24sB4sB8s': uid, user id (string), verify type, time, punch state, reserved. */
export function decodeRecord40(r: Buffer): AttRecord {
  const userId = r.subarray(2, 26).toString("latin1").split("\0")[0]!.trim();
  return { deviceUserId: userId, localTime: decodeTime(r.readUInt32LE(27)), status: String(r[31]), verifyMode: String(r[26]), workcode: "0" };
}

/** '<I4sBB2sI': user id (number), time, verify type, punch state, reserved, workcode. */
export function decodeRecord16(r: Buffer): AttRecord {
  return { deviceUserId: String(r.readUInt32LE(0)), localTime: decodeTime(r.readUInt32LE(4)), status: String(r[9]), verifyMode: String(r[8]), workcode: String(r.readUInt32LE(12)) };
}

export function encodeRecord40(rec: { uid: number } & Omit<AttRecord, "workcode">): Buffer {
  const b = Buffer.alloc(40);
  b.writeUInt16LE(rec.uid & 0xffff, 0);
  b.write(rec.deviceUserId, 2, 24, "latin1");
  b[26] = Number(rec.verifyMode) & 0xff;
  b.writeUInt32LE(encodeTime(rec.localTime), 27);
  b[31] = Number(rec.status) & 0xff;
  return b;
}

export function encodeRecord16(rec: AttRecord): Buffer {
  const b = Buffer.alloc(16);
  b.writeUInt32LE(Number(rec.deviceUserId), 0);
  b.writeUInt32LE(encodeTime(rec.localTime), 4);
  b[8] = Number(rec.verifyMode) & 0xff;
  b[9] = Number(rec.status) & 0xff;
  b.writeUInt32LE(Number(rec.workcode), 12);
  return b;
}

// ── Other replies ────────────────────────────────────────────────────────

/** CMD_GET_FREE_SIZES: 20 little-endian int32 (pyzk read_sizes). */
export function parseFreeSizes(data: Buffer): { users: number; records: number; recordCapacity: number } | null {
  if (data.length < 80) return null;
  const f = (i: number) => data.readInt32LE(i * 4);
  return { users: f(4), records: f(8), recordCapacity: f(16) };
}

/** CMD_OPTIONS_RRQ replies "~Name=value\0…". */
export function parseOptionValue(data: Buffer): string | null {
  const text = data.toString("latin1").split("\0")[0] ?? "";
  const eq = text.indexOf("=");
  const value = eq >= 0 ? text.slice(eq + 1).trim() : "";
  return value || null;
}

export function cString(data: Buffer): string | null {
  const s = data.toString("latin1").split("\0")[0]?.trim() ?? "";
  return s || null;
}

// ── Errors ───────────────────────────────────────────────────────────────

export class ProtocolError extends Error {
  readonly name = "ProtocolError";
}
export class UnsupportedFormatError extends Error {
  readonly name = "UnsupportedFormatError";
}
